package com.optarena.echo;

import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class EchoController {

    @GetMapping(value = "/echo", produces = MediaType.TEXT_PLAIN_VALUE)
    public ResponseEntity<String> echo(@RequestParam(required = false) String input) {
        String value = (input == null) ? "" : input;
        if (value.isBlank()) {
            return ResponseEntity.badRequest().body("Error: input must not be blank (received: '" + value + "')");
        }
        return ResponseEntity.ok("You said: " + value);
    }
}
